		'Wallet number or InstaPay address you transfer from' => 'رقم المحفظة أو عنوان إنستاباي الذي تحوّل منه',
		'Transaction id you entered' => 'رقم العملية الذي كتبته',
		'Transfer' => 'التحويل',
